package keys;

/** Read and written by property: no field of the identifier attributes' names. */
public class GateKey {
    private String c;
    private int n;

    public String getCode() { return c; }
    public void setCode(String code) { c = code; }
    public int getNumber() { return n; }
    public void setNumber(int number) { n = number; }
}
